# Generic FitAI reference foods that this library replaces in search results (avoids near-duplicates).
REPLACES_REFERENCE = {"rice", "roti", "idli", "sambar", "dal", "poha", "curd", "paneer", "ghee", "milk", "banana", "egg"}

INDIAN_FOODS: dict[str, dict] = {}
for key, name, aliases, cat, kcal, p, c, f, diet, allergens, servings in _ROWS:
    INDIAN_FOODS[key] = {
        "key": key, "name": name, "aliases": [a.strip() for a in aliases.split(",") if a.strip()], "category": cat,
        "kcal": kcal, "protein": p, "carbs": c, "fat": f, "diet": diet, "allergens": allergens,
        "servings": [{"label": lbl, "grams": g} for lbl, g in servings],
    }
